# Diese alten Kategorien beschrieben den Aufbewahrungsort ("Kühlschrank", "Vorrat") bzw.
# haben ihre Bedeutung geändert ("Backzutaten" enthielt auch Brot) → anhand des Namens neu
# einsortieren. Alle anderen Kategorien wurden bewusst gewählt und bleiben unangetastet.
RESORT_FALLBACKS = {
    "fridge": "dairy",   # Kühlschrank → meist Milchprodukte
    "pantry": "other",
    "baking": "baking",
    "other": "other",
}


def resort_categories(apps, schema_editor):
    from ingredients.categories import guess_category

    Ingredient = apps.get_model("ingredients", "Ingredient")
    for ingredient in Ingredient.objects.filter(category__in=RESORT_FALLBACKS):
        new_category = guess_category(ingredient.name, default=RESORT_FALLBACKS[ingredient.category])
        if new_category != ingredient.category:
            ingredient.category = new_category
            ingredient.save(update_fields=["category"])


def back_to_old(apps, schema_editor):
    Ingredient = apps.get_model("ingredients", "Ingredient")
    Ingredient.objects.filter(category__in=["dairy", "meat_fish"]).update(category="fridge")
    Ingredient.objects.filter(category__in=["grains", "canned"]).update(category="pantry")
    Ingredient.objects.filter(category="bread").update(category="baking")


